import { BlogPost } from '../types';
import { getApiOrigin } from './config';

const API_URL = `${getApiOrigin()}/api/blog`;

const getHeaders = () => {
  return {
    'Content-Type': 'application/json',
    'Accept': 'application/json'
  };
};

const handleResponse = async (res: Response) => {
  const contentType = res.headers.get("content-type");
  if (contentType && contentType.includes("application/json")) {
    const json = await res.json();
    if (!res.ok) {
      throw new Error(json.error || json.message || `API Error: ${res.status}`);
    }
    return json;
  } else {
    // Fallback for HTML errors (404/500 from server)
    const text = await res.text();
    console.error(`Non-JSON response from ${res.url}:`, text.substring(0, 100));
    throw new Error(`API Error: ${res.status} (Invalid Response Format)`);
  }
};

export const blogApi = {
  // Public: Get all public posts
  // GET /api/blog
  getAllPublic: async (): Promise<BlogPost[]> => {
    try {
      const res = await fetch(`${API_URL}`, {
        method: 'GET',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include' 
      });
      return await handleResponse(res);
    } catch (error) {
      console.error('Fetch public posts failed:', error);
      return [];
    }
  },

  // Public: Get single post by slug
  // GET /api/blog/:slug
  getBySlug: async (slug: string): Promise<BlogPost | null> => {
    try {
      const res = await fetch(`${API_URL}/${slug}`, {
        method: 'GET',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include'
      });
      
      // Handle 404 gracefully without throwing
      if (res.status === 404) {
        return null;
      }
      
      return await handleResponse(res);
    } catch (error) {
      console.error('Fetch single post failed:', error);
      return null;
    }
  },

  // Protected: Get single post by ID
  // GET /api/blog/:id
  getById: async (id: string): Promise<BlogPost | null> => {
    try {
      const res = await fetch(`${API_URL}/${id}`, {
        method: 'GET',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include'
      });
      
      // Handle 404 gracefully without throwing
      if (res.status === 404) {
        return null;
      }
      
      return await handleResponse(res);
    } catch (error) {
      console.error('Fetch post by ID failed:', error);
      return null;
    }
  },

  // Protected: Get user's own posts (Public + Drafts + Pending)
  // Combines public posts (filtered) + private posts (from /me/posts)
  getMyPosts: async (userId: string): Promise<BlogPost[]> => {
    try {
      // 1. Fetch all Public posts and filter for this user
      // (Backend GET / returns only public)
      const publicRes = await fetch(`${API_URL}`, {
        method: 'GET',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include'
      });
      const allPublic: BlogPost[] = await handleResponse(publicRes);
      const myPublic = allPublic.filter(p => {
          if (typeof p.authorId === 'string') return p.authorId === userId;
          if (typeof p.authorId === 'object' && p.authorId._id) return p.authorId._id === userId;
          return false;
      });

      // 2. Fetch Private posts (Drafts, Pending) from new endpoint
      // GET /api/blog/me/posts
      const privateRes = await fetch(`${API_URL}/me/posts`, {
        method: 'GET',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include'
      });
      const myPrivate: BlogPost[] = await handleResponse(privateRes);

      // 3. Merge and Sort by Date (newest first)
      const merged = [...myPublic, ...myPrivate];
      // Deduplicate by ID just in case
      const seen = new Set();
      const unique = merged.filter(p => {
          const duplicate = seen.has(p._id);
          seen.add(p._id);
          return !duplicate;
      });
      
      return unique.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

    } catch (error) {
      console.warn('Fetch user posts failed:', error);
      return [];
    }
  },

  // Protected: Get posts for moderation panel
  // GET /api/blog/panel
  // Admins see: draft, pending, rejected
  // Moderators see: pending
  getModerationPosts: async (): Promise<BlogPost[]> => {
    // Removed try/catch wrapper to allow errors to propagate to the UI
    const res = await fetch(`${API_URL}/panel`, {
      method: 'GET',
      headers: getHeaders(),
      mode: 'cors',
      credentials: 'include'
    });

    // Specific check for route ordering issue
    if (res.status === 404) {
       console.error("CRITICAL: /api/blog/panel returned 404. This usually means the backend route is defined AFTER a dynamic route like '/:id'. Please move router.get('/panel') above any dynamic routes.");
       throw new Error("Endpoint not found (404). Backend route ordering issue suspected.");
    }

    return await handleResponse(res);
  },

  // Deprecated wrapper for backward compatibility
  getPending: async (): Promise<BlogPost[]> => {
      return await blogApi.getModerationPosts();
  },

  // Protected: Create new post
  // POST /api/blog
  create: async (data: Partial<BlogPost>): Promise<{ success: boolean; message: string; post?: BlogPost }> => {
    try {
      const res = await fetch(`${API_URL}`, {
        method: 'POST',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include',
        body: JSON.stringify({
            ...data,
            // Ensure we send 'publish' flag if visibility is pending
            publish: data.visibility === 'pending'
        })
      });
      const json = await handleResponse(res);
      // Backend returns the post object directly on 201
      return { success: true, message: 'Post created successfully', post: json };
    } catch (error: any) {
      return { success: false, message: error.message };
    }
  },

  // Protected: Update post
  // PATCH /api/blog/:id
  update: async (id: string, data: Partial<BlogPost>): Promise<{ success: boolean; message: string; post?: BlogPost }> => {
    try {
      const res = await fetch(`${API_URL}/${id}`, {
        method: 'PATCH',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include',
        body: JSON.stringify(data)
      });
      const json = await handleResponse(res);
      return { success: true, message: 'Post updated successfully', post: json };
    } catch (error: any) {
      return { success: false, message: error.message };
    }
  },

  // Protected: Submit post for approval
  // POST /api/blog/:id/submit
  submit: async (id: string): Promise<{ success: boolean; message: string }> => {
    try {
      const res = await fetch(`${API_URL}/${id}/submit`, {
        method: 'POST',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include',
        body: JSON.stringify({}) // Empty body for POST
      });
      await handleResponse(res);
      return { success: true, message: 'Post submitted for approval' };
    } catch (error: any) {
      return { success: false, message: error.message };
    }
  },

  // Admin: Approve post
  // POST /api/blog/:id/approve
  approve: async (id: string): Promise<{ success: boolean; message: string }> => {
    try {
      const res = await fetch(`${API_URL}/${id}/approve`, {
        method: 'POST',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include',
        body: JSON.stringify({})
      });
      await handleResponse(res);
      return { success: true, message: 'Post approved' };
    } catch (error: any) {
      return { success: false, message: error.message };
    }
  },

  // Admin: Reject post
  // POST /api/blog/:id/reject
  reject: async (id: string, reason?: string): Promise<{ success: boolean; message: string }> => {
    try {
      const res = await fetch(`${API_URL}/${id}/reject`, {
        method: 'POST',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include',
        body: JSON.stringify({ reason: reason })
      });
      await handleResponse(res);
      return { success: true, message: 'Post rejected' };
    } catch (error: any) {
      return { success: false, message: error.message };
    }
  },

  // Protected: Delete post
  // DELETE /api/blog/:id
  delete: async (id: string): Promise<{ success: boolean; message: string }> => {
    try {
      const res = await fetch(`${API_URL}/${id}`, {
        method: 'DELETE',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include'
      });
      const json = await handleResponse(res);
      return { success: true, message: json.message || 'Post deleted' };
    } catch (error: any) {
      return { success: false, message: error.message };
    }
  },

  // Protected: Toggle Like
  // POST /api/blog/:id/toggle-like
  toggleLike: async (id: string): Promise<{ liked: boolean; likesCount: number }> => {
    try {
      const res = await fetch(`${API_URL}/${id}/toggle-like`, {
        method: 'POST',
        headers: getHeaders(),
        mode: 'cors',
        credentials: 'include',
        body: JSON.stringify({})
      });
      return await handleResponse(res);
    } catch (error: any) {
       throw error;
    }
  }
};
